   135  // createInternalLB creates an internal load balancer for the cluster.  In
   136  // GCP this entails creating a health check, backend service, and one forwarding rule
   137  // per specified subnet pointing to that backend service.
   138  func (b *APILoadBalancerBuilder) createInternalLB(c *fi.CloudupModelBuilderContext) error {
   139  	clusterLabel := gce.LabelForCluster(b.ClusterName())
   140  
   141  	hc := &gcetasks.HealthCheck{
   142  		Name:      s(b.NameForHealthCheck("api")),
   143  		Port:      wellknownports.KubeAPIServer,
   144  		Lifecycle: b.Lifecycle,
   145  	}
   146  	c.AddTask(hc)
   147  	var igms []*gcetasks.InstanceGroupManager
   148  	for _, ig := range b.InstanceGroups {
   149  		if ig.Spec.Role != kops.InstanceGroupRoleControlPlane {
   150  			continue
   151  		}
   152  		if len(ig.Spec.Zones) > 1 {
   153  			return fmt.Errorf("instance group %q has %d zones, which is not yet supported for GCP", ig.GetName(), len(ig.Spec.Zones))
   154  		}
   155  		if len(ig.Spec.Zones) == 0 {
   156  			return fmt.Errorf("instance group %q must specify exactly one zone", ig.GetName())
   157  		}
   158  		zone := ig.Spec.Zones[0]
   159  		igms = append(igms, &gcetasks.InstanceGroupManager{Name: s(gce.NameForInstanceGroupManager(b.Cluster.ObjectMeta.Name, ig.ObjectMeta.Name, zone)), Zone: s(zone)})
   160  	}
   161  	bs := &gcetasks.BackendService{
   162  		Name:                  s(b.NameForBackendService("api")),
   163  		Protocol:              s("TCP"),
   164  		HealthChecks:          []*gcetasks.HealthCheck{hc},
   165  		Lifecycle:             b.Lifecycle,
   166  		LoadBalancingScheme:   s("INTERNAL"),
   167  		InstanceGroupManagers: igms,
   168  	}
   169  	c.AddTask(bs)
   170  
   171  	network, err := b.LinkToNetwork()
   172  	if err != nil {
   173  		return err
   174  	}
   175  
   176  	for _, sn := range b.Cluster.Spec.Networking.Subnets {
   177  		var subnet *gcetasks.Subnet
   178  		for _, ig := range b.InstanceGroups {
   179  			if ig.HasAPIServer() && slices.Contains(ig.Spec.Subnets, sn.Name) {
   180  				subnet = b.LinkToSubnet(&sn)
   181  				break
   182  			}
   183  		}
   184  		if subnet == nil {
   185  			continue
   186  		}
   187  
   188  		ipAddress := &gcetasks.Address{
   189  			Name:          s(b.NameForIPAddress("api-" + sn.Name)),
   190  			IPAddressType: s("INTERNAL"),
   191  			Purpose:       s("SHARED_LOADBALANCER_VIP"),
   192  			Subnetwork:    subnet,
   193  
   194  			WellKnownServices: []wellknownservices.WellKnownService{wellknownservices.KubeAPIServer},
   195  			Lifecycle:         b.Lifecycle,
   196  		}
   197  		c.AddTask(ipAddress)
   198  
   199  		c.AddTask(&gcetasks.ForwardingRule{
   200  			Name:                s(b.NameForForwardingRule("api-" + sn.Name)),
   201  			Lifecycle:           b.Lifecycle,
   202  			BackendService:      bs,
   203  			Ports:               []string{strconv.Itoa(wellknownports.KubeAPIServer)},
   204  			IPAddress:           ipAddress,
   205  			IPProtocol:          "TCP",
   206  			LoadBalancingScheme: s("INTERNAL"),
   207  			Network:             network,
   208  			Subnetwork:          subnet,
   209  			Labels: map[string]string{
   210  				clusterLabel.Key: clusterLabel.Value,
   211  				"name":           "api-" + sn.Name,
   212  			},
   213  		})
   214  		if b.Cluster.UsesNoneDNS() {
   215  			ipAddress.WellKnownServices = append(ipAddress.WellKnownServices, wellknownservices.KopsController)
   216  
   217  			fr := &gcetasks.ForwardingRule{
   218  				Name:                s(b.NameForForwardingRule("kops-controller-" + sn.Name)),
   219  				Lifecycle:           b.Lifecycle,
   220  				BackendService:      bs,
   221  				Ports:               []string{strconv.Itoa(wellknownports.KopsControllerPort)},
   222  				IPAddress:           ipAddress,
   223  				IPProtocol:          "TCP",
   224  				LoadBalancingScheme: s("INTERNAL"),
   225  				Network:             network,
   226  				Subnetwork:          subnet,
   227  				Labels: map[string]string{
   228  					clusterLabel.Key: clusterLabel.Value,
   229  					"name":           "kops-controller-" + sn.Name,
   230  				},
   231  			}
   232  			// We previously created a forwarding rule which was external; prune it
   233  			fr.PruneForwardingRulesWithName(b.NameForForwardingRule("kops-controller")) // , "Removing legacy external load balancer for kops-controller")
   234  
   235  			c.AddTask(fr)
   236  		}
   237  	}
   238  	return nil
   239  }
